-- 0026 — Photos in buyer–seller messages.
--
-- A message can carry one photo (a defect, a size question, a proof of
-- delivery) as well as, or instead of, text. The photo lives in a PRIVATE
-- bucket, message-media: only the two people in the conversation see it,
-- through short-lived signed URLs the server makes after its own check
-- (lib/data.ts). Paths are generated by the server
-- (<conversation id>/<uuid>.jpg|png), never chosen by a browser.
--
-- image_alt is the sender's description of the photo, read out by screen
-- readers in place of the image: several sellers and buyers here are blind.
--
-- Surface B: im_messages keeps its 0006 read rule (participants and admins)
-- and gains no write rule; the bucket gets a RESTRICTIVE deny for the client
-- roles, as pwd-ids (0017), so no permissive storage policy can open it.

begin;

alter table public.im_messages
add column if not exists image_path text;

alter table public.im_messages
add column if not exists image_alt text;

-- A photo-only message has no text.
alter table public.im_messages alter column body set default '';

alter table public.im_messages
drop constraint if exists im_messages_has_content;

alter table public.im_messages
add constraint im_messages_has_content check (
    length(btrim (body)) > 0
    or image_path is not null
) not valid;

alter table public.im_messages
drop constraint if exists im_messages_image_path_shape;

alter table public.im_messages
add constraint im_messages_image_path_shape check (
    image_path is null
    or image_path ~ '^[0-9]+/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png)$'
);

alter table public.im_messages
drop constraint if exists im_messages_image_alt_length;

alter table public.im_messages
add constraint im_messages_image_alt_length check (
    image_alt is null
    or length(image_alt) <= 300
);

-- ---------------------------------------------------------------------------
-- Private bucket for message photos (1 MB, JPEG or PNG; the browser resizes)
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('message-media', 'message-media', false, 1048576, array['image/jpeg', 'image/png'])
on conflict (id) do update
  set public = false,
      file_size_limit = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists im_message_media_deny_clients on storage.objects;

create policy im_message_media_deny_clients on storage.objects as restrictive for all to anon,
authenticated using (bucket_id <> 'message-media')
with
    check (bucket_id <> 'message-media');

commit;